import SwiftUI
import Charts
import Combine

private enum Theme {
    static let background=Color(red:0.045,green:0.058,blue:0.078)
    static let sidebar=Color(red:0.035,green:0.047,blue:0.065)
    static let panel=Color(red:0.068,green:0.085,blue:0.110)
    static let accent=Color(red:0.27,green:0.88,blue:0.76)
    static let blue=Color(red:0.34,green:0.62,blue:1)
    static let muted=Color(red:0.54,green:0.60,blue:0.69)
    static let border=Color.white.opacity(0.07)
}
struct Panel<Content:View>:View {
    let title:String;var subtitle:String="";@ViewBuilder let content:Content
    var body:some View{VStack(alignment:.leading,spacing:16){if !title.isEmpty{VStack(alignment:.leading,spacing:4){Text(title).font(.system(size:15,weight:.semibold));if !subtitle.isEmpty{Text(subtitle).font(.system(size:11)).foregroundStyle(Theme.muted)}}};content}.padding(20).frame(maxWidth:.infinity,alignment:.leading).background(Theme.panel,in:RoundedRectangle(cornerRadius:14)).overlay(RoundedRectangle(cornerRadius:14).stroke(Theme.border))}
}
struct Badge:View {let text:String;var color:Color=Theme.accent;var body:some View{HStack(spacing:6){Circle().fill(color).frame(width:5,height:5);Text(text).font(.system(size:10,weight:.semibold))}.padding(.horizontal,9).padding(.vertical,6).foregroundStyle(color).background(color.opacity(0.10),in:Capsule())}}
struct StatCard:View {let title:String;let value:String;let detail:String;let icon:String;var color:Color=Theme.accent
    var body:some View{VStack(alignment:.leading,spacing:13){HStack{Text(title.uppercased()).font(.system(size:10,weight:.semibold)).tracking(1).foregroundStyle(Theme.muted);Spacer();Image(systemName:icon).foregroundStyle(color)};Text(value).font(.system(size:28,weight:.semibold,design:.rounded)).monospacedDigit();Text(detail).font(.system(size:11)).foregroundStyle(Theme.muted).lineLimit(1)}.padding(18).frame(maxWidth:.infinity,alignment:.leading).background(Theme.panel,in:RoundedRectangle(cornerRadius:14)).overlay(RoundedRectangle(cornerRadius:14).stroke(Theme.border))}
}
struct RootView:View {
