            HStack(spacing:12){Image(systemName:"wifi").font(.system(size:23,weight:.medium)).foregroundStyle(Theme.accent).frame(width:40,height:40).background(Theme.accent.opacity(0.09),in:RoundedRectangle(cornerRadius:12));VStack(alignment:.leading,spacing:3){Text("ARCHER").font(.system(size:15,weight:.bold)).tracking(2.3);Text("CONTROL CENTER").font(.system(size:8,weight:.medium)).tracking(1.6).foregroundStyle(Theme.muted)}}.padding(.bottom,35)
