    private func heading(_ title:String,_ subtitle:String)->some View{VStack(alignment:.leading,spacing:7){Text(title).font(.system(size:27,weight:.semibold));Text(subtitle).font(.system(size:12)).foregroundStyle(Theme.muted)}.frame(maxWidth:.infinity,alignment:.leading)}
    private var overview:some View{
        ScrollView{VStack(alignment:.leading,spacing:22){
            HStack(alignment:.top){heading("Tu radio, en perspectiva.","Estado USB actual y análisis de una captura guardada.");Badge(text:"ANÁLISIS LOCAL")}
            if model.device.mode != .wifi { notice("Estado USB actual: \(model.device.title.lowercased()). Las gráficas y resultados de abajo pertenecen a una captura guardada.",color:Theme.muted) }
            integrityWarnings
            HStack(spacing:14){StatCard(title:"Paquetes decodificados",value:model.details.capture.packets.count.formatted(),detail:"\(model.details.capture.byteCount.formatted(.byteCount(style:.file))) en la vista",icon:"square.stack.3d.up");StatCard(title:"Redes observadas",value:"\(model.details.capture.networks.count)",detail:"Beacons y probe responses válidos",icon:"wifi",color:Theme.blue);StatCard(title:"RX pairwise",value:model.selected?.nativeLog == nil ? "—":"\(model.details.native.pairwise)",detail:"Autenticado por el ejecutor",icon:"lock.shield");StatCard(title:"Contexto guardado",value:model.device.context,detail:model.device.remaining.map{"\($0) secuencias libres"} ?? "Reservas sin verificar",icon:"cpu",color:model.device.context=="CLEAN" ? Theme.accent:.orange)}
            HStack(alignment:.top,spacing:16){Panel(title:"Actividad de radio",subtitle:"Paquetes por intervalo · captura seleccionada"){rateChart;HStack(spacing:20){legend("Gestión",Theme.blue);legend("Datos",Theme.accent);legend("Control",.gray);legend("Otros",.gray.opacity(0.4));Spacer();Text(String(format:"%.1f s",model.details.capture.duration)).font(.system(size:10,design:.monospaced)).foregroundStyle(Theme.muted)}}.frame(maxWidth:.infinity);Panel(title:"Señal observada",subtitle:"RSSI de las tramas de la captura, en dBm"){signalChart;HStack{Image(systemName:"antenna.radiowaves.left.and.right");Text("Medición radiotap, no velocidad de Internet")}.font(.system(size:10)).foregroundStyle(Theme.muted)}.frame(width:300)}
            HStack(alignment:.top,spacing:16){Panel(title:"Verificación del enlace",subtitle:"Resultado del registro seleccionado"){phaseRow("WPA2",model.details.native.security);phaseRow("ACK DHCP",model.details.native.lease);phaseRow("ARP pairwise",model.details.native.arp);phaseRow("ICMP",model.details.native.echo);phaseRow("Retirada de contexto",model.details.native.cleanup);Divider();HStack{Text("Interfaz de red macOS").font(.system(size:11));Spacer();Text("PENDIENTE").font(.system(size:9,weight:.semibold)).foregroundStyle(.orange)}}.frame(width:300);Panel(title:"Redes en la captura",subtitle:"Selección de las redes observadas; no es un escaneo en vivo"){if model.details.capture.networks.isEmpty{empty("No hay redes decodificadas",icon:"wifi.slash")}else{ForEach(Array(model.details.capture.networks.prefix(4))){network in networkRow(network);if network.id != model.details.capture.networks.prefix(4).last?.id{Divider().opacity(0.4)}}};Button("Ver todas las redes →"){model.page = .networks}.buttonStyle(.plain).foregroundStyle(Theme.accent).font(.system(size:11))}}
            if let selected=model.selected{HStack{Image(systemName:"doc.zipper").foregroundStyle(Theme.muted);Text(selected.title).font(.system(size:11,design:.monospaced));Spacer();Text(selected.date,style:.date).font(.system(size:10)).foregroundStyle(Theme.muted);Button("Mostrar archivos"){model.revealCapture()}.buttonStyle(.plain).foregroundStyle(Theme.accent).font(.system(size:11))}.padding(.top,1)}
        }.padding(28)}
    }
    @ViewBuilder private var integrityWarnings:some View{
        if model.details.pcapVerified==false || model.details.nativeVerified==false{notice("Un archivo cambió respecto a su manifiesto. Revisa los originales antes de usar este resultado como evidencia.",color:.orange)}
        if !model.details.monitorWarning.isEmpty{notice(model.details.monitorWarning,color:.orange)}
        if !model.details.error.isEmpty{notice(model.details.error,color:Theme.muted)}
        if let warning=model.details.capture.warnings.first{notice(warning,color:.orange)}
    }
    private func notice(_ text:String,color:Color)->some View{HStack(alignment:.top,spacing:9){Image(systemName:"info.circle");Text(text).fixedSize(horizontal:false,vertical:true);Spacer(minLength:0)}.font(.system(size:11)).foregroundStyle(color).padding(12).frame(maxWidth:.infinity,alignment:.leading).background(color.opacity(0.07),in:RoundedRectangle(cornerRadius:9))}
    private func phaseRow(_ title:String,_ passed:Bool)->some View{let verified=passed && model.details.nativeVerified==true;return HStack{Image(systemName:verified ? "checkmark.circle.fill":"circle.dashed").foregroundStyle(verified ? Theme.accent:Theme.muted);Text(title).font(.system(size:12));Spacer();Text(verified ? "Verificado":"Sin comprobar").font(.system(size:10)).foregroundStyle(verified ? Theme.accent:Theme.muted)}}
