        }.padding(28)}}
    private func modeCard(_ title:String,_ description:String,_ icon:String,available:Bool)->some View{let active=model.analysisMode==title;return Button{if available{model.analysisMode=title;if title=="Análisis PCAP"{model.page = .traffic}}}label:{VStack(alignment:.leading,spacing:15){HStack{Image(systemName:icon).font(.system(size:22)).foregroundStyle(available ? Theme.accent:Theme.muted);Spacer();Image(systemName:available ? (active ? "checkmark.circle.fill":"circle"):"lock.fill").foregroundStyle(active ? Theme.accent:Theme.muted).font(.system(size:12))};Text(title).font(.system(size:14,weight:.semibold));Text(description).font(.system(size:11)).foregroundStyle(Theme.muted).fixedSize(horizontal:false,vertical:true).frame(minHeight:48,alignment:.top);Text(available ? "DISPONIBLE":"PENDIENTE").font(.system(size:8,weight:.bold)).tracking(1).foregroundStyle(available ? Theme.accent:Theme.muted)}.padding(19).frame(maxWidth:.infinity,alignment:.leading).background(Theme.panel,in:RoundedRectangle(cornerRadius:12)).overlay(RoundedRectangle(cornerRadius:12).stroke(active ? Theme.accent.opacity(0.5):Theme.border))}.buttonStyle(.plain).disabled(!available)}
    private var activityPage:some View{ScrollView{VStack(alignment:.leading,spacing:22){heading("Lo que ocurrió","Eventos del ejecutor para la captura seleccionada; no es un registro de conexión del sistema.");Panel(title:"Secuencia del ensayo",subtitle:model.details.nativeVerified==true ? "Registro coincide con el SHA256 del manifiesto":"Registro sin verificación de manifiesto"){if model.details.native.events.isEmpty{empty("Este archivo no incluye eventos del ejecutor",icon:"list.bullet.rectangle").frame(height:250)};ForEach(model.details.native.events){event in HStack(alignment:.top,spacing:14){Image(systemName:event.success ? "checkmark.circle.fill":"exclamationmark.circle.fill").foregroundStyle(event.success ? Theme.accent:.orange);VStack(alignment:.leading,spacing:5){Text(event.title).font(.system(size:13,weight:.medium));if !event.detail.isEmpty{Text(event.detail).font(.system(size:11)).foregroundStyle(Theme.muted)}};Spacer();Text("fila \(event.id+1)").font(.system(size:9,design:.monospaced)).foregroundStyle(Theme.muted)}.padding(.vertical,6)}};Panel(title:"Reportes TX de firmware",subtitle:"TX_DONE no confirma procesamiento de RELEASE por el servidor"){HStack{ForEach(Array(model.details.native.reports.enumerated()),id:\.offset){_,report in VStack(spacing:8){Text("TAG \(report.tag)").font(.system(size:9,weight:.semibold)).foregroundStyle(Theme.muted);Text(report.state==0 ? "TX_DONE":"Estado \(report.state)").font(.system(size:11,weight:.semibold)).foregroundStyle(report.state==0 ? Theme.accent:.orange);Text("count \(report.count)").font(.system(size:9,design:.monospaced)).foregroundStyle(Theme.muted)}.padding(14).frame(maxWidth:.infinity).background(Color.white.opacity(0.025),in:RoundedRectangle(cornerRadius:8))}}};Panel(title:"Integridad del PCAP",subtitle:"SHA256 calculado sobre el archivo seleccionado"){Text(model.details.pcapDigest.isEmpty ? "Sin PCAP":model.details.pcapDigest).font(.system(size:11,design:.monospaced)).textSelection(.enabled);Badge(text:model.details.pcapVerified==true ? "COINCIDE CON EL MANIFIESTO":model.details.pcapVerified==false ? "NO COINCIDE":"SIN HASH DE REFERENCIA",color:model.details.pcapVerified==false ? .orange:Theme.muted)}}.padding(28)}}
    private var footer:some View{HStack(spacing:8){Circle().fill(model.device.mode == .wifi ? Theme.accent:Theme.muted).frame(width:5,height:5);Text(model.message.isEmpty ? "Datos locales · \(model.project.lastPathComponent)":model.message).lineLimit(1);Spacer();Text(model.details.pcapVerified==true ? "PCAP íntegro":"Archivo local");Text("•");Text("Interfaz macOS pendiente")}.font(.system(size:9)).foregroundStyle(Theme.muted).padding(.horizontal,28).padding(.vertical,11).background(Theme.sidebar)}
}
